 function text(t,size,color,tx=x,tw=width,align=w.align,wrap=w.wrap){for(const l of lines(t,size,tw,wrap)){const dx=align==='center'?(tw-measure(l,size))/2:align==='right'?tw-measure(l,size):0;html+=`<span class="widget-text" style="left:${tx+dx}px;top:${y}px;font-size:${size}px;line-height:${Math.ceil(size*1.2)}px;color:${color}">${esc(l)||' '}</span>`;y+=Math.ceil(size*1.2);}}
 if(inline){const oldy=y,nw=measure(w.label+' ',w.nameSize);text(w.label+' ',w.nameSize,w.nameColor,x,width,w.nameAlign||'left',false);y=oldy;text(formatValue(p,w),w.valueSize,w.color,x+nw,Math.max(1,width-nw),w.valueAlign||'left');}
 else{if(name)text(w.label,w.nameSize,w.nameColor,x,width,w.nameAlign||w.align);if(name&&val)y+=3;if(val)text(formatValue(p,w),w.valueSize,w.color,x,width,w.valueAlign||w.align);}
