  const active=document.activeElement;
  // Replace only display contents; preserve widgets, drag handles and focused inputs.
  for(const el of $$('[data-widget]')){const w=p.widgets.find(w=>w.id===el.dataset.widget);const content=el.querySelector(':scope > .widget-content');if(w&&content){content.outerHTML=widgetContent(w);const background=el.querySelector(':scope > .widget-background');if(background)background.style.background=effectiveWidget(p,w).bg;}}
